        public virtual async Task<Response<VolumePathItem>> UploadVolumeFileAsync(string volumeName, BinaryData content, string path = default, bool? overwrite = default, CancellationToken cancellationToken = default)
        {
            Argument.AssertNotNullOrEmpty(volumeName, nameof(volumeName));
            Argument.AssertNotNull(content, nameof(content));

            Response result = await UploadVolumeFileAsync(volumeName, RequestContent.Create(content), path, overwrite, cancellationToken.ToRequestContext()).ConfigureAwait(false);
            return Response.FromValue((VolumePathItem)result, result);
        }
    }
}
